import {LightningElement} from 'lwc';export default class Probe extends LightningElement {prevent=false;result='pending';renderedCallback(){if(this.result==='pending')this.result='ready';}open(){this.template.querySelector('lightning-rich-text-toolbar-button').showPopup();}enablePrevent(){this.prevent=true;}clickout(e){let out={type:e.type,bubbles:e.bubbles,cancelable:e.cancelable,composed:e.composed,prevent:this.prevent};if(this.prevent)e.preventDefault();out.defaultPrevented=e.defaultPrevented;this.result=JSON.stringify(out);}}